{"command":"$files = Get-ChildItem -Path 'Script/Blueprint/Prefabs/Monsters/MainScene' -Recurse -Filter 'BaseMons.lua'
$changed = @()
foreach ($file in $files) {
    $path = $file.FullName
    $text = [System.IO.File]::ReadAllText($path, [System.Text.Encoding]::UTF8)
    $original = $text

    if ($text -notmatch 'PlayerLevelMgr') {
        $text = $text -replace 'local L_Enum = UGCGameSystem\.UGCRequire\("Script\.Lin\.L_Enum"\)', 'local L_Enum = UGCGameSystem.UGCRequire("Script.Lin.L_Enum")' + "`r`n" + 'local PlayerLevelMgr = UGCGameSystem.UGCRequire("Script.Lin.PlayerLevelMgr")'
    }

    if ($text -notmatch 'PlayerLevelMgr:AddExp\(EventInstigator, KillExp\)') {
        $pattern = "(?s)(\r?\n\s+end\r?\n\r?\n\s+TaskMgr:RequestAddTaskProgress)"
        $replacement = "`r`n        --[[----------------------怪物死亡给击杀者加经验------------------------]] --`r`n        local KillExp = PlayerLevelMgr:GetWaveKillExp(self.MonsterID)`r`n        PlayerLevelMgr:AddExp(EventInstigator, KillExp)`r`n    end`r`n`r`n    TaskMgr:RequestAddTaskProgress"
        $text = [System.Text.RegularExpressions.Regex]::Replace($text, $pattern, $replacement, 1)
    }

    if ($text -ne $original) {
        [System.IO.File]::WriteAllText($path, $text, [System.Text.Encoding]::UTF8)
        $changed += $file.FullName
    }
}
$changed | ForEach-Object { $_ }
"ChangedCount=$($changed.Count)"","workdir":"C:\WeGameApps\rail_apps\OasisEraEditor(2001776)\ShadowTrackerExtra\UGCProjects\Douluo","timeout_ms":10000}

