{"command":"$files = Get-ChildItem -Path 'Script/Blueprint/Prefabs/Monsters/MainScene' -Recurse -Filter 'BaseMons.lua'
$total = $files.Count
$requireCount = 0
$addExpCount = 0
$missing = @()
foreach ($file in $files) {
    $text = [System.IO.File]::ReadAllText($file.FullName, [System.Text.Encoding]::UTF8)
    $hasRequire = $text -match 'local PlayerLevelMgr = UGCGameSystem\.UGCRequire\("Script\.Lin\.PlayerLevelMgr"\)'
    $hasAdd = $text -match 'PlayerLevelMgr:AddExp\(EventInstigator, KillExp\)'
    if ($hasRequire) { $requireCount++ }
    if ($hasAdd) { $addExpCount++ }
    if (-not ($hasRequire -and $hasAdd)) { $missing += $file.FullName }
}
